INSERT INTO `hqs` (`id`, `titulo`, `descricao`, `generos`, `autor`, `lancamento`, `imagens`, `link1`, `link2`, `link3`, `loja1`, `loja2`, `loja3`) VALUES
(1, 'Invencível #144 - O fim de todas as coisas', 'Acompanha Mark Grayson, um adolescente que descobre ser filho de um super-herói e herda poderes fantásticos, enquanto navega por um mundo de super-heróis e enfrenta desafios pessoais e existenciais.', 'Ação / Ficção Científica', 'Robert Kirkman', '2018-02-14', 'h1.webp', 'https://www.amazon.com.br/Invincible-144-English-Robert-Kirkman-ebook/dp/B076HZQJHC#detailBullets_feature_div (Kindle, edição em inglês)', 'https://books.apple.com/br/book/invincible-144/id1342767886 (Apple books, edição em inglês)', NULL, 'Amazon', 'Apple Books', NULL),
(2, 'Homem-Aranha: Miles Morales #1', 'Quando o enfurecido Rino e um grupo de criminosos misteriosos começam a atormentar o Brooklyn, as coisas ficam feias para o jovem Homem-Aranha! Que mistérios o aguardam por trás deste novo levante de vilões? Por que o Rino tem lacaios? E quem é o novo antagonista que pode ter acabado de se tomar o inimigo mais poderoso de Miles? Talvez o Capitão América tenha as respostas! E mais: antes de vestir o uniforme, Miles Morales era apenas... Miles Morales: estudante recém-matriculado na Academia de Visões do Brooklyn com poderes de aranha secretos! Quando uma Invasão Secreta de Skrulls vira Manhattan ao avesso, Miles precisa escolher: seus grandes poderes vêm com grandes responsabilidades?', 'Ação / Aventura', 'Saladin Ahmed', '2019-10-01', 'miles_morales_1.jpg', 'https://www.amazon.com/Miles-Morales-Homem-Aranha-vol-Portuguese-ebook/dp/B08X8R6P3W?utm_source=chatgpt.com', 'https://www.rika.com.br/miles-morales---homem-aranha--1---direto-do-brooklyn-15008013/p?srsltid=AfmBOoqWllP3tj702Owx1GnyacTxDxUZNZTa7MymSGPWbMDK_JqY6CfK&utm_source=chatgpt.com', 'https://leitura.com.br/miles-morales-homem-aranha-vol-1-L030-9788542625615?srsltid=AfmBOooo30NbIrN-1dsFvEQAWoF1mEmwgtwhMlbHbgwlWkoRAhiJvhBa&utm_source=chatgpt.com', 'Amazon', 'Rika Comic Shop', 'Leitura'),
(3, 'Batman: A piada mortal ', 'Do premiado roteirista Alan Moore (Watchmen, V de Vingança) conta como um dia ruim na vida de um homem pode significar a linha que separa a sanidade da loucura. Principalmente quando se trata do Coringa, o maior e mais conhecido vilão do mundo dos quadrinhos. Os desenhos de Brian Bolland (Camelot 3000), um dos maiores ilustradores dos quadrinhos, elevaram a história praticamente à perfeição retratando com maestria o mundo imaginado por Alan Moore. Mas faltava um detalhe para completar a obra. Bolland não pôde colorir a edição original, e agora, vinte anos depois, isso foi corrigido e as cores foram completamente refeitas pelo artista, seguindo fielmente a sua imaginação. Edição obrigatória para os fãs do Coringa, do Batman e dos quadrinhos.', 'Drama / Crime', 'Alan Moore', '1988-03-29', 'joker.webp', 'https://www.amazon.com.br/Batman-Piada-Mortal-Alan-Moore/dp/8573515473', 'https://panini.com.br/batman-a-piada-mortal-edicao-absoluta?srsltid=AfmBOopo4V7D8Hz97xtl6GUtOgex_3_xgmRwnvq0to4zyOWCz_M_2yQP', 'https://lista.mercadolivre.com.br/batman-a-piada-mortal-1988?utm_source=chatgpt.com', 'Amazon', 'Panini', 'Mercado Livre'),
(4, 'Flash – A guerra dos gorilas', 'Descrição: Ele é conhecido como Rei Grodd, o implacável déspota de Gorilla City (lar de uma espécie superevoluída e hiperinteligente de símios). Acreditando ter sido escolhido para portar o poder da Força de Aceleração – a fonte das assombrosas habilidades do Flash –, Grodd está convicto de que o herói roubou seu direito de nascença… e veio com um exército para garantir que ele o devolva. E se uma cidade humana, e todos os seus habitantes, precisarem morrer no processo, que assim seja. Para deter essa que é a maior ameaça que já encarou, o Velocista Escarlate vai precisar se aliar a companheiros de batalha bem incomuns: a mesma Galeria de Vilões que ele vem enfrentando há anos! A vitória é incerta e virá a um alto custo. Mas, mesmo que chegue, pode significar apenas o prenúncio de uma batalha muito maior chegando no horizonte…', 'Ação / Ficção Científica ', 'Francis Manapul', '2015-09-21', 'flash.jpg', 'https://www.amazon.com.br/Flash-Guerra-Gorilas-Francis-Manapul/dp/8583681988', 'https://www.lojascaverna.com.br/produtos/flash-a-guerra-dos-gorilas/', 'https://produto.mercadolivre.com.br/MLB-2114494356-flash-a-guerra-dos-gorilas-panini-2016-capa-dura-_JM', 'Amazon', 'Lojas Caverna', 'Mercado Livre'),
(5, 'Nêmesis ', 'O bilionário Matthew Anderson decidiu se tornar o maior supervilão do mundo. Com inteligência, tecnologia avançada e crueldade sem limites, ele desafia a lei e aterroriza os maiores detetives do planeta. Seu próximo alvo: o chefe de polícia Blake Morrow. Em uma caçada mortal, Nêmesis prova que, quando um gênio do crime está no controle, ninguém está seguro.', 'Suspense / Terror', 'Mark Millar', '2010-06-24', 'hq8.png', 'https://www.amazon.com.br/Nêmesis-1-Mark-Millar/dp/8565484394', 'https://www.magazineluiza.com.br/hq-nemesis-panini/p/cd5jg675h3/li/hqlv/', NULL, 'Amazon', 'Magazine Luiza', NULL),
(6, 'Justiceiro MAX #1 – No Princípio', 'Frank Castle, o Justiceiro, declara guerra total contra o crime organizado. Nesta HQ, ele enfrenta a poderosa família criminosa Gnucci enquanto lida com seu próprio passado sombrio. Com uma abordagem brutal e realista, essa história marca o início da icônica fase MAX, trazendo um Justiceiro mais violento e implacável do que nunca.', 'Ação / Policial', 'Garth Ennis', '2018-06-22', 'justiceiro.jpg', 'https://www.amazon.com.br/Justiceiro-No-Princípio-Garth-Ennis/dp/8583682941', 'https://sp.olx.com.br/sao-paulo-e-regiao/livros-e-revistas/justiceiro-no-principio-edicao-deluxe-1403613891?lis=listing_no_category', 'https://www.mercadolivre.com.br/justiceiro-no-principio-de-ennis-garth-editorial-panini-brasil-ltda-capa-dura-em-portugus-2018/p/MLB19223139', 'Amazon', 'Olx', 'Mercado Livre'),
(7, 'Quarteto Fantástico - O fim', 'Num futuro distante, o Quarteto Fantástico é reverenciado por ter levado a humanidade a uma nova Era de Ouro. O sistema solar foi colonizado, mas há muito tempo a heroíca família debandou. Agora, um misterioso oponente do passado ameaça destruir tudo o que eles lutaram tanto para criar. O Quarteto precisará se reunir — não só pelo bem da família, mas pela sobrevivência de toda a galáxia. Este volume reúne as edições 1–6 de Fantastic Four: The End.', 'Drama / Ficção Científica', 'Alan Davis', '2014-01-01', 'quarteto_fantastico.jpg', 'https://www.amazon.com.br/Quarteto-Fant%C3%A1stico-Cole%C3%A7%C3%A3o-Oficial-Graphic/dp/B08W4PC598', 'https://www.estantevirtual.com.br/busca/quarteto-fantastico-o-fim', 'https://lista.mercadolivre.com.br/quarteto-fant%C3%A1stico-o-fim#D[A:quarteto%20fant%C3%A1stico%20o%20fim]', 'Amazon', 'Estante Virtual', 'Mercado Livre'),
(8, 'Um Passeio no Inferno #1 – Início da Queda', 'Uma investigação do FBI sobre o desaparecimento de dois agentes os leva até um depósito sinistro ligado a um atentado terrorista. Lá, descobrem um homem envolvido com segredos obscuros e uma conspiração que vai além da compreensão. Terror psicológico, violência e tensão se misturam nessa HQ intensa escrita por Garth Ennis.', 'Terror Psicológico / Drama', 'Garth Ennis', '2022-11-30', 'hq9.png', 'https://www.amazon.com.br/Um-passeio-no-inferno-1/dp/8550820172', 'https://www.ugrapress.com.br/produtos/um-passeio-no-inferno/', 'https://www.mercadolivre.com.br/um-passeio-no-inferno-de-garth-ennis-editora-alta-geek-capa-mole-em-portugus-2022/p/MLB30580917', 'Amazon', 'Ugra Press', 'Mercado Livre'),
(9, 'Watchmen - Edição Definitiva', 'Num mundo alternativo à beira da guerra nuclear, super-heróis são reais — mas falhos, corrompidos e perseguidos. Quando um ex-membro dos vigilantes mascarados é assassinado, uma conspiração vem à tona, revelando segredos obscuros e colocando o destino da humanidade em risco. Watchmen é uma narrativa densa e crítica sobre poder, moralidade e o verdadeiro significado do heroísmo.', 'Drama', 'Alan Moore', '2022-03-04', 'watchmen.jpg', 'https://www.amazon.com.br/Watchmen-V%C3%A1rios-Autores/dp/857351549X', 'https://www.estantevirtual.com.br/livro/watchmen-edicao-definitiva-HNF-9043-000', 'https://lista.mercadolivre.com.br/watchmen-edicao-definitiva', 'Amazon', 'Estante Virtual', 'Mercado Livre'),
(10, 'Monstro do Pântano - Raízes do Mal | vol. 1', 'Após um trágico acidente, o cientista Alec Holland renasce como uma criatura elemental ligada à flora da Terra: o Monstro do Pântano. Nesta reinvenção revolucionária escrita por Alan Moore, a HQ mergulha em temas existenciais, terror e natureza, enquanto o Monstro descobre sua verdadeira origem e enfrenta ameaças sobrenaturais que desafiam a lógica humana.', 'Terror / Suspense', 'Alan Moore', '2017-01-01', 'pântano.jpg', 'https://www.amazon.com.br/Monstro-P%C3%A2ntano-Ra%C3%ADzes-Mal-Vol/dp/B07QZCTM31', 'https://lista.mercadolivre.com.br/cl%C3%A1ssicos-dc-monstro-do-p%C3%A2ntano-ra%C3%ADzes', 'https://www.rika.com.br/monstro-do-pantano---raizes-do-mal--1-15006194/p?srsltid=AfmBOoro4Mz9EIyeOFRsNY8ILw6CTnHlvlcdcJ9iaSDeoDjJBYmBdGAd', 'Amazon', 'Mercado Livre', 'Rika Comic Shop'),
(11, 'Gideon Falls - O Celeiro Negro | vol. 1', 'A trama acompanha dois personagens principais: Norton Sinclair, um jovem recluso obcecado por encontrar \"artefatos\" no lixo que ele acredita estarem ligados a uma conspiração; e o Padre Fred, um sacerdote com um passado conturbado que é transferido para a pequena cidade de Gideon Falls, repleta de segredos obscuros. As vidas de ambos se entrelaçam em torno da misteriosa lenda do Celeiro Negro, uma estrutura enigmática que aparece e reaparece ao longo da história, trazendo morte e loucura em seu rastro.', 'Terror / Suspense', 'Jeff Lemire', '2021-03-10', 'gideon_falls.jpg', 'https://www.amazon.com.br/Gideon-Falls-Jeff-Lemire/dp/8569032412', 'https://www.estantevirtual.com.br/livro/gideon-falls-volume-1-068-5114-000-BK', 'https://produto.mercadolivre.com.br/MLB-4671571570-livro-gideon-falls-volume-1-o-celeiro-negro-_JM', 'Amazon', 'Estante Virtual', 'Mercado Livre'),
(12, 'Batman Amaldiçoado ', 'Após a misteriosa morte do Coringa, Batman acorda ferido e desorientado. Conforme investiga o caso, ele começa a ser assombrado por visões sombrias e eventos sobrenaturais. Para desvendar esse mistério, o Cavaleiro das Trevas contará com a ajuda de John Constantine e outros personagens do lado oculto do Universo DC. Uma história madura, repleta de suspense e terror psicológico.', 'Suspense / Terror Psicológico / Sobrenatural', 'Brian Azzarello', '2019-07-07', 'batman_amaldicoado.png', 'https://www.amazon.com.br/Batman-Amaldi%C3%A7oado-Brian-Azzarello/dp/8542625420', 'https://www.estantevirtual.com.br/livro/batman-amaldicoado-HZR-9088-000', 'https://comicboom.com.br/produto/batman-amaldicoado/', 'Amazon', 'Estante Virtual', 'Comic Boom');
